export const mutations = mutationTree(state, {
  setOnlineUsers(state, users) {
    state.onlineUsers = users
  },
  setUsers(state, users) {
    state.users = users
  },
  setMetrics(state, metrics) {
    state.metrics = metrics
  }
})
