<script>
export default {
  props: ['apps'],
  emits: ['update'],
  methods: {
    addApp() {
      const newApps = [...this.apps, {
        name: '',
        icon: 'fa-globe',
        description: '',
        path: '',
        port: null,
        roles: ['admin'],
        is_vnc: false,
        scheme: 'http'
      }]
      this.$emit('update', newApps)
    },
    removeApp(idx) {
      const newApps = this.apps.filter((_, i) => i !== idx)
      this.$emit('update', newApps)
    },
    toggleRole(app, role) {
      if (!app.roles) app.roles = []
      const idx = app.roles.indexOf(role)
      if (idx > -1) {
        app.roles.splice(idx, 1)
      } else {
        app.roles.push(role)
      }
    }
  }
}
</script>
